using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ── CalculateTotal: DataRow-driven tests ────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0,  50.00,  DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00,  5, 0.10, 0.00,   DisplayName = "Zero price")]
    [DataRow(10.00, 0, 0.10, 0.00,   DisplayName = "Zero quantity")]
    [DataRow(99.99, 1, 1.0,  199.98, DisplayName = "Max tax rate (100%)")]
    public void CalculateTotal_ReturnsExpectedResult(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ── CalculateTotal: DynamicData from a method ───────────────────────

    public static IEnumerable<object[]> LargeOrderCases
    {
        get
        {
            yield return [100.00m, 1000, 0.07m, 107_000.00m, "Bulk order with 7% tax"];
            yield return [0.01m,   1,    0.0m,  0.01m,       "Minimum price, no tax"];
            yield return [9999.99m, 2,   0.15m, 22_999.977m, "High-value items with 15% tax"];
        }
    }

    [TestMethod]
    [DynamicData(nameof(LargeOrderCases))]
    public void CalculateTotal_DynamicData_ReturnsExpectedResult(
        decimal unitPrice, int quantity, decimal taxRate, decimal expected, string scenario)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expected, result, $"Failed for scenario: {scenario}");
    }

    // ── CalculateTotal: invalid-input tests ─────────────────────────────

    [TestMethod]
    [DataRow(-1.0, 1,  0.1, "unitPrice",  DisplayName = "Negative unit price")]
    [DataRow(10.0, -1, 0.1, "quantity",    DisplayName = "Negative quantity")]
    [DataRow(10.0, 1,  -0.1, "taxRate",    DisplayName = "Negative tax rate")]
    [DataRow(10.0, 1,  1.1,  "taxRate",    DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidInput_ThrowsArgumentOutOfRange(
        double unitPrice, int quantity, double taxRate, string expectedParam)
    {
        var ex = Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParam, ex.ParamName);
    }

    // ── ApplyDiscount: DataRow-driven tests ─────────────────────────────

    [TestMethod]
    [DataRow(100.00, 0.0,   100.00, DisplayName = "No discount")]
    [DataRow(100.00, 10.0,  90.00,  DisplayName = "10% discount")]
    [DataRow(100.00, 50.0,  50.00,  DisplayName = "50% discount")]
    [DataRow(100.00, 100.0, 0.00,   DisplayName = "100% discount (free)")]
    [DataRow(49.99,  25.0,  37.4925, DisplayName = "Fractional result")]
    [DataRow(0.00,   50.0,  0.00,   DisplayName = "Zero price with discount")]
    public void ApplyDiscount_ReturnsExpectedResult(
        double price, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    // ── ApplyDiscount: DynamicData from a method ────────────────────────

    public static IEnumerable<object[]> InvalidDiscountCases
    {
        get
        {
            yield return [100.00m, -1.0m,  "Below zero"];
            yield return [100.00m, 100.1m, "Above 100"];
            yield return [100.00m, -50.0m, "Far below zero"];
        }
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountCases))]
    public void ApplyDiscount_InvalidDiscount_ThrowsArgumentOutOfRange(
        decimal price, decimal discountPercent, string scenario)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent),
            $"Expected exception for scenario: {scenario}");
    }
}

